let assetName;
const callApi = async function() {
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }

  // Get 'eventIds' from the URL parameters
  const urlParams = new URLSearchParams(window.location.search);
  const eventIds = urlParams.get('eventIds');

  if (!eventIds) {
    console.error('eventIds parameter not found in the URL');
    return;
  }

  // Split 'eventIds' by comma to handle multiple IDs
  const eventIdArray = eventIds.split(',');

  for (let eventId of eventIdArray) {
    try {
      const response = await fetch(`http://localhost:8081/case-definition/fault-history/eventIds?eventIds=${encodeURIComponent(eventId)}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!response.ok) {
        throw new Error(`API call failed with status: ${response.status}`);
      }

      const data = await response.json();

      // Check if there's any item with AssetName
      const assetNameItem = data.find(item => item.AssetName);

      if (assetNameItem) {
        assetName = assetNameItem.AssetName;
       
        return assetName; // Return assetName if found
      }

    } catch (error) {
      console.error('Error calling the API for eventId:', eventId, error);
    }
  }

  return null; // Return null if no AssetName was found in any API call
};

// Define the calculateValue function for the Form.io component
component.calculateValue = function() {
  return assetName || 'Loading...'; // Show 'Loading...' until assetName is set
};

// Use callApi to fetch the value and set it when available
callApi().then(apiAssetName => {
  if (apiAssetName) {
    assetName = apiAssetName; // Update assetName
    
  } else {
    console.error('No AssetName found in API response.');
  }
}).catch(error => {
  console.error('Error occurred in callApi:', error);
});

const callApi = function() {
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }

  // Get 'eventIds' from the URL parameters
  const urlParams = new URLSearchParams(window.location.search);
  const eventIds = urlParams.get('eventIds');

  if (!eventIds) {
    console.error('eventIds parameter not found in the URL');
    return;
  }

  // Encode the eventIds to be passed as a comma-separated string in the API request
  const encodedEventIds = encodeURIComponent(eventIds);

  // Make a single API call for all eventIds
  fetch(`http://localhost:8081/case-definition/fault-history/eventIds?eventIds=${encodedEventIds}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`
    }
  })
  .then(response => {
    if (!response.ok) {
      throw new Error(`API call failed with status: ${response.status}`);
    }
    return response.json();
  })
  .then(data => {
    if (Array.isArray(data)) {
      const mappedData = data.map(item => {
        const creationDate = item.eventEnrichment?.creationDate || 'Default Value';

        // Format the creation date to display only the date (YYYY-MM-DD)
        const formattedDate = creationDate !== 'Default Value' 
          ? new Date(creationDate).toLocaleString('en-GB', {
              day: '2-digit',
              month: '2-digit',
              year: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
              hour12: true
            }).replace(/\//g, '-') // Replace "/" with "-" to get dd-MM-yyyy format
          : 'Default Value';

        return {
          'textField1': 'Default Value',
          'textField2': item.events?.eventName || 'Default Value',
          'textField3': item.events?.eventName || 'Default Value',
          'textField4': item.eventCategory?.name || 'Default Value',
          'TextFaultStartTimeDate': formattedDate // Only date part
        };
      });

      // Assign the mapped data to component.calculateValue
      component.calculateValue = mappedData;
    } else {
      console.error('Data is not an array or is undefined:', data);
    }
  })
  .catch(error => {
    console.error('Error during API call:', error);
  });
};

// Call the function
callApi();

